/*  Pokemon FRLG Autostory Script
 *
 *  From: https://github.com/PokemonAutomation/
 *
 *  Data types of the generated story (PokemonFRLG_AutoStoryData.h): the
 *  legs to walk and the steps of each segment. The story is generated by
 *  tools/route_generator from the pret/pokefirered map data and scripts.
 *
 *  Everything is stored in flat constant arrays that refer to each other by
 *  index, so the large generated file compiles quickly and needs no
 *  initialization at run time.
 *
 */

#ifndef PokemonAutomation_PokemonFRLG_AutoStoryScript_H
#define PokemonAutomation_PokemonFRLG_AutoStoryScript_H

#include <stddef.h>
#include <stdint.h>
#include <iterator>
#include <vector>
#include "NintendoSwitch/Controllers/NintendoSwitch_ControllerButtons.h"

namespace PokemonAutomation{
namespace NintendoSwitch{
namespace PokemonFRLG{


//  How a straight run of tiles is walked.
enum class RunKind : uint8_t{
    WALK,               //  Plain tiles: one continuous input.
    CHECKED,            //  Wild-encounter tiles: one step at a time, watching for a battle.
    CHECKED_TRAINER,    //  In sight of a trainer that turns around: one step at a time.
    JUMP,               //  Over a ledge: one input, two tiles.
    SPIN,               //  Carried by spinner tiles: "count" tiles without input.
    SURF,               //  Surfing over water without encounters.
    SURF_CHECKED,       //  Surfing over water with encounters.
    DISMOUNT,           //  From the water onto land: one step.
};

//  What happens at the end of a leg.
enum class LegEnd : uint8_t{
    STOP,           //  Stand still.
    WARP_PUSH,      //  Hold "push" to take a door, mat or stairs warp.
    WARP_STEP,      //  The last step lands on a warp (ladder, hole, warp pad, cave entrance).
    TRIGGER,        //  The last step lands on a script trigger: a scene starts.
    INTERACT,       //  Turn to "face" something to talk to or use.
};

//  The area picture the game shows when the warp at the end of a leg enters
//  a dungeon area from another area (src/map_preview_screen.c). The player
//  cannot move while it is shown.
enum class MapPreview : uint8_t{
    NONE,
    FOREST,         //  Drawn over the new map, 40-120 frames and a cross-fade.
    CAVE,           //  Full screen picture before the map fades in. Holding B skips it.
};

struct StoryRun{
    DpadPosition direction;
    uint16_t count;
    RunKind kind;
};

struct StoryLeg{
    const char* name;
    uint32_t first_run;         //  Index into StoryScript::runs.
    uint16_t run_count;
    DpadPosition start_facing;  //  Facing at the start, if known (DPAD_NONE otherwise).
    DpadPosition push;          //  For WARP_PUSH.
    DpadPosition face;          //  For INTERACT.
    LegEnd end;
    bool dark;                  //  The leg starts on a map that is dark without Flash.
    bool dest_dark;             //  The warp at the end leads to a dark map.
    MapPreview preview;         //  Shown after the warp at the end.
};

enum class StepType : uint8_t{
    WALK,               //  leg
    TALK,               //  A, read through the text
    TALK_YES,           //  A, answer YES
    TALK_NO,            //  A, answer NO
    HEAL,               //  talk to the nurse, heal
    CUTSCENE,           //  p0 = min ms, p1 = max ms, text "YES": answer questions with YES
    BATTLE,             //  a battle starts (or started on the way); p1 = 1: run away if wild
    SCRIPTED_BATTLE,    //  the first rival battle
    SAVE,               //  p0 = 1 if the start menu has POKeDEX
    GRIND,              //  p0 = level, p1 = battles between heals, dir = back and forth,
                        //  legs_a = to grass, legs_b = to nurse, legs_c = back to grass
    TEACH_HM,           //  p0 = HM rank in the TM Case, p1 = party slot (1-6),
                        //  p2 = move slot to forget (-1: decide), text = move
    CATCH,              //  text = species slugs (comma separated), p0 = balls, dir = back and forth
    WAIT,               //  p0 = ms
    PUZZLE,             //  text = name; legs_a = hub->targets, legs_b = targets->hub
    PRESS,              //  text = button, p0 = times, p1 = ms between
    ELEVATOR,           //  p0 = floor cursor now, p1 = floor to pick
    OSCILLATE,          //  walk back and forth (dir) until a scene starts; p0 = max ms
    PUSH,               //  push a Strength boulder toward dir
    BUY,                //  in a Poke Mart menu: p0 = item index, p1 = quantity
    HEAL_ITEMS,         //  heal the party with items from the bag
};

struct StoryStep{
    StepType type;
    const char* label;
    int32_t leg;
    int32_t p0;
    int32_t p1;
    int32_t p2;
    DpadPosition dir;
    const char* text;
    uint32_t legs_a;    //  Offsets into StoryScript::leg_lists (0 = none).
    uint32_t legs_b;
    uint32_t legs_c;
};

struct StorySegment{
    const char* id;
    const char* title;
    int32_t chapter;
    bool has_dex;
    uint32_t first_step;    //  Index into StoryScript::steps.
    uint32_t step_count;
};

struct StoryScript{
    const StoryRun* runs;
    size_t run_count;
    const StoryLeg* legs;
    size_t leg_count;
    const int32_t* leg_lists;
    size_t leg_list_size;
    const StoryStep* steps;
    size_t step_count;
    const StorySegment* segments;
    size_t segment_count;

    const StoryLeg& leg(int32_t index) const{
        return legs[(size_t)index];
    }
    const StoryRun* leg_runs(const StoryLeg& leg) const{
        return runs + leg.first_run;
    }
    const StoryStep& step(const StorySegment& segment, size_t index) const{
        return steps[segment.first_step + index];
    }
    std::vector<int32_t> leg_list(uint32_t offset) const{
        std::vector<int32_t> ret;
        if (offset == 0 || offset >= leg_list_size){
            return ret;
        }
        int32_t count = leg_lists[offset];
        for (int32_t i = 0; i < count; i++){
            ret.push_back(leg_lists[offset + 1 + (uint32_t)i]);
        }
        return ret;
    }
};


}
}
}
#endif
